#include "../../experiments/engine_lab/TransitionPeakResearch.h"
#include "../../experiments/engine_lab/ColorSplitNative.h"
using namespace skell_lab;
extern "C" int reconstruction_guard(int mode,double fs,const double* x,double* y,unsigned n){if(!x||!y||!n||mode<0||mode>1||fs<8000||fs>384000||!std::isfinite(fs))return 0;ReconstructionGuard g;g.prepare(fs,-1,60,mode==1);for(unsigned i=0;i<n+16;++i){auto z=g.process(i<n?Frame{x[2*i],x[2*i+1]}:Frame{0,0});if(i>=16){y[2*(i-16)]=z.l;y[2*(i-16)+1]=z.r;}}return 1;}
extern "C" int transition_render(double fs,const double* x,double* y,unsigned n){if(!x||!y||!n||!std::isfinite(fs)||fs<8000||fs>384000)return 0;TransitionDelay2 d;if(!d.prepare(fs,fs*.12+.5,1,.7,1))return 0;for(unsigned i=0;i<n;++i){double delay=fs*(i<n/3?.12:i<2*n/3?.18:.09)+.5;auto z=d.process({x[2*i],x[2*i+1]},delay);y[2*i]=z.l;y[2*i+1]=z.r;}return 1;}
template<class T> void render(T& e,double fs,const double*x,double*y,unsigned n){e.prepare(fs,12,.12,1,0);for(unsigned i=0;i<n+T::latency;++i){auto z=e.process(i<n?Frame{x[2*i],x[2*i+1]}:Frame{0,0});if(i>=T::latency){y[2*(i-T::latency)]=z.l;y[2*(i-T::latency)+1]=z.r;}}}
extern "C" int selective_color(int mode,double fs,const double* x,double*y,unsigned n){if(!x||!y||!n||!std::isfinite(fs)||fs<8000||fs>384000)return 0;switch(mode){case 0:{ColorSplitNative<4,40,450,450> e;render(e,fs,x,y,n);break;}case 1:{ColorSplitNative<4,40,450,475> e;render(e,fs,x,y,n);break;}case 2:{ColorSplitNative<4,80,450,475> e;render(e,fs,x,y,n);break;}case 3:{ColorSplitNative<4,80,465,475> e;render(e,fs,x,y,n);break;}default:return 0;}return 1;}
